    # ---------- 50. 寓兴 ----------
    {
        "id": "jia-dao-50",
        "title": "寓兴",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷49》",
        "verse": [
            "真集道方至，貌殊妒还多。山泉入城池，自然生浑波。",
            "今时出古言，在众翻为讹。有琴含正韵，知音者如何。",
            "一生足感激，世言忽嵯峨。不得市井味，思响吾岩阿。",
            "浮华岂我事，日月徒蹉跎。旷哉颍阳风，千载无其他。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 51. 怀郑从志 ----------
    {
        "id": "jia-dao-51",
        "title": "怀郑从志",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷50》",
        "verse": [
            "西风吹阴云，雨雪半夜收。忽忆天涯人，起看斗与牛。",
            "故人别二年，我意如百秋。音信两杳杳，谁云昔绸缪。",
            "平明一封书，寄向东北舟。翩翩春归鸟，会自为匹俦。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 52. 易州登龙兴寺楼望郡北高峰 ----------
