    # ---------- 110. 题李凝幽居 ----------
    {
        "id": "jia-dao-110",
        "title": "题李凝幽居",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "五言律诗",
        "year": "约元和间",
        "source": "《全唐诗·卷五七二》",
        "verse": [
            "闲居少邻并，草径入荒园。鸟宿池边树，僧敲月下门。",
            "过桥分野色，移石动云根。暂去还来此，幽期不负言。",
        ],
        "tijie": "此诗写访李凝幽居，「僧敲月下门」一句曾与韩愈论「推敲」二字，遂成诗坛佳话。诗写幽居之静与访友之趣。",
        "notes": [
            ("李凝", "贾岛友人，隐士。"),
            ("邻并", "邻居。"),
            ("敲", "贾岛原欲用「推」，韩愈建议用「敲」，后世称「推敲」。"),
            ("云根", "云起山石处，指石。"),
            ("幽期", "隐逸之约。"),
        ],
        "appreciation": "首联「闲居少邻并，草径入荒园」写幽居之僻、荒园之静。颔联「鸟宿池边树，僧敲月下门」为千古名句：以「敲」字写月下访友，有声衬静，且「敲」比「推」更合礼数情境，经韩愈定为「敲」，遂成炼字典范。颈联「过桥分野色，移石动云根」写园中之景，野色分桥、云根动石，幽邃如画。尾联写去而必来，不负幽约。全诗以「敲」字为眼，于幽静中见生机，贾岛瘦硬清空之格具见。",
        "famous": [
            ("鸟宿池边树，僧敲月下门。", "炼字典范，「推敲」佳话。"),
        ],
        "sources": [
            "《全唐诗》卷五七二",
            "《唐诗鉴赏辞典》贾岛条（上海辞书出版社，1983）",
            "《苕溪渔隐丛话》载推敲事",
        ],
    },
