    # ---------- 132. 寄武功姚主簿 ----------
    {
        "id": "jia-dao-132",
        "title": "寄武功姚主簿",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷70》",
        "verse": [
            "居枕江沱北，情悬渭曲西。数宵曾梦见，几处得书披。",
            "驿路穿荒坂，公田带淤泥。静棋功奥妙，闲作韵清凄。",
            "锄草留丛药，寻山上石梯。客回河水涨，风起夕阳低。",
            "空地苔连井，孤村火隔溪。卷帘黄叶落，锁印子规啼。",
            "陇色澄秋月，边声入战鼙。会须过县去，况是屡招携。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 133. 题刘华书斋 ----------
    {
        "id": "jia-dao-133",
        "title": "题刘华书斋",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷71》",
        "verse": [
            "白石床无尘，青松树有鳞。一莺啼带雨，两树合从春。",
            "荒榭苔胶砌，幽丛果堕榛。偶来疏或数，当暑夕胜晨。",
            "露滴星河水，巢重草木薪。终南同往意，赵北独游身。",
            "渡叶司天漏，惊蛩远地人。机清公干族，也莫卧漳滨。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 134. 送卢秀才游潞府 ----------
