    # ---------- 310. 崔卿池上双白鹭 ----------
    {
        "id": "jia-dao-310",
        "title": "崔卿池上双白鹭",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷11》",
        "verse": [
            "鹭雏相逐出深笼，顶各有丝茎数同。洒石多霜移足冷，",
            "隔城远树挂巢空。其如尽在滩声外，何似双飞浦色中。",
            "见此池潭卿自凿，清泠太液底潜通。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 311. 送胡道士 ----------
    {
        "id": "jia-dao-311",
        "title": "送胡道士",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷12》",
        "verse": [
            "短褐身披满渍苔，灵溪深处观门开。却从城里移琴去，",
            "许到山中寄药来。临水古坛秋醮罢，宿杉幽鸟夜飞回。",
            "丹梯愿逐真人上，日夕归心白发催。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 312. 寄韩潮州愈 ----------
    {
        "id": "jia-dao-312",
        "title": "寄韩潮州愈",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷13》",
        "verse": [
            "此心曾与木兰舟，直到天南潮水头。隔岭篇章来华岳，",
            "出关书信过泷流。峰悬驿路残云断，海浸城根老树秋。",
            "一夕瘴烟风卷尽，月明初上浪西楼。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 313. 酬张籍王建 ----------
    {
        "id": "jia-dao-313",
        "title": "酬张籍王建",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷14》",
        "verse": [
            "疏林荒宅古坡前，久住还因太守怜。渐老更思深处隐，",
            "多闲数得上方眠。鼠抛贫屋收田日，雁度寒江拟雪天。",
            "身是龙钟应是分，水曹芸阁枉来篇。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 314. 逢博陵故人彭兵曹 ----------
    {
        "id": "jia-dao-314",
        "title": "逢博陵故人彭兵曹",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷15》",
        "verse": [
            "曲阳分散会京华，见说三年住海涯。别后解餐蓬虆子，",
            "向前未识牧丹花。偶逢日者教求禄，终傍泉声拟置家。",
            "蹋雪携琴相就宿，夜深开户斗牛斜。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 315. 赠牛山人 ----------
    {
        "id": "jia-dao-315",
        "title": "赠牛山人",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷16》",
        "verse": [
            "二十年中饵茯苓，致书半是老君经。东都旧住商人宅，",
            "南国新修道士亭。凿石养峰休买蜜，坐山秤药不争星。",
            "古来隐者多能卜，欲就先生问丙丁。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 316. 送于中丞使回纥册立 ----------
    {
        "id": "jia-dao-316",
        "title": "送于中丞使回纥册立",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷17》",
        "verse": [
            "君立天骄发使车，册文字字著金书。渐通青冢乡山尽，",
            "欲达皇情译语初。调角寒城边色动，下霜秋碛雁行疏。",
            "旌旗来往几多日，应向途中见岁除。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 317. 送刘侍御重使江西 ----------
    {
        "id": "jia-dao-317",
        "title": "送刘侍御重使江西",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷18》",
        "verse": [
            "时当苦热远行人，石壁飞泉溅马身。又到钟陵知务大，",
            "还浮湓浦属秋新。早程猿叫云深极，宿馆禽惊叶动频。",
            "前者已闻廉使荐，兼言有画静边尘。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 318. 赠圆上人 ----------
    {
        "id": "jia-dao-318",
        "title": "赠圆上人",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷19》",
        "verse": [
            "诵经千纸得为僧，麈尾持行不拂蝇。古塔月高闻咒水，",
            "新坛日午见烧灯。一双童子浇红药，百八真珠贯彩绳。",
            "且说近来心里事，仇雠相对似亲朋。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 319. 处州李使君改任遂州因寄赠 ----------
    {
        "id": "jia-dao-319",
        "title": "处州李使君改任遂州因寄赠",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷20》",
        "verse": [
            "庭树几株阴入户，主人何在客闻蝉。钥开原上高楼锁，",
            "瓶汲池东古井泉。趁静野禽曾后到，休吟邻叟始安眠。",
            "仙都山水谁能忆，西去风涛书满船。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 320. 酬慈恩寺文郁上人 ----------
    {
        "id": "jia-dao-320",
        "title": "酬慈恩寺文郁上人",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷21》",
        "verse": [
            "袈裟影入禁池清，犹忆乡山近赤城。篱落罅间寒蟹过，",
            "莓苔石上晚蛩行。期登野阁闲应甚，阻宿山房疾未平。",
            "闻说又寻南岳去，无端诗思忽然生。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
    # ---------- 321. 访鉴玄师侄 ----------
