    # ---------- 397. 送友人之南陵 ----------
    {
        "id": "jia-dao-397",
        "title": "送友人之南陵",
        "author": "贾岛",
        "poet_id": "jia-dao",
        "dynasty": "唐",
        "genre": "古诗",
        "year": "",
        "source": "《全唐诗·卷98》",
        "verse": [
            "莫叹徒劳向宦途，不群气岸有谁如。南陵暂掌仇香印，",
            "北阙终行贾谊书。好趁江山寻胜境，莫辞韦杜别幽居。",
            "少年跃马同心使，免得诗中道跨驴。",
        ],
        "tijie": "",
        "notes": [],
        "appreciation": "",
        "famous": [],
        "sources": ["《全唐诗》曹寅本"],
    },
